CREATE FUNCTION public.prepare_referral_funding_version(_distribution uuid,_env text,_terms text,_refund text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_distributions;p public.network_fee_policies;v jsonb;subtotal bigint;processing bigint;total bigint;BEGIN IF NOT public.network_source_access(_distribution,true) OR _env NOT IN ('sandbox','live') OR _terms<>'2026-11-07' OR _refund<>'2026-11-07' OR NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='referral_funding_version_preparation' AND enabled) THEN RAISE EXCEPTION 'Funding unavailable'; END IF; SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution FOR UPDATE; IF d.id IS NULL OR d.amount_cents<=0 OR d.selected_offer_id IS NOT NULL OR d.current_radius IS NOT NULL THEN RAISE EXCEPTION 'Offer changed or already distributed'; END IF; SELECT * INTO p FROM public.network_fee_policies WHERE environment=_env AND method_category='card' AND active ORDER BY version DESC LIMIT 1; IF p.id IS NULL OR p.sandbox_estimate OR p.percent_bps<0 OR p.percent_bps>=10000 THEN RAISE EXCEPTION 'Approved fee configuration required'; END IF; subtotal:=d.amount_cents+round(d.amount_cents::numeric*200/10000)::bigint;processing:=ceil((subtotal+p.fixed_cents)::numeric/(1-p.percent_bps::numeric/10000))-subtotal;IF p.cap_cents IS NOT NULL THEN processing:=least(processing,p.cap_cents);END IF; total:=subtotal+processing; IF total>2147483647 THEN RAISE EXCEPTION 'Amount too large';END IF;v:=jsonb_build_object('id',gen_random_uuid(),'version',jsonb_array_length(d.funding_versions)+1,'offerVersionAmountCents',d.amount_cents,'receiverCents',d.amount_cents,'networkFeeCents',subtotal-d.amount_cents,'processingRecoveryCents',processing,'senderTotalCents',total,'senderMarginCents',NULL,'feePolicyVersion',p.version,'termsVersion',_terms,'refundVersion',_refund,'acceptedAt',NULL,'funded',false,'preparedAt',now(),'personMfnId',(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid())); UPDATE public.trip_distributions SET funding_versions=funding_versions||jsonb_build_array(v),funding_required=true WHERE id=d.id;PERFORM public.network_audit(d.id,NULL,'funding_version_prepared',jsonb_build_object('version',v->'version','funded',false));RETURN v; END $$;
REVOKE ALL ON FUNCTION public.prepare_referral_funding_version(uuid,text,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.prepare_referral_funding_version(uuid,text,text,text) TO authenticated;
CREATE POLICY master_responsibility_review_read ON public.fin_admin_actions FOR SELECT TO authenticated USING(responsibility_evidence IS NOT NULL AND public.has_role(auth.uid(),'admin'));
COMMENT ON COLUMN public.trip_distributions.funding_versions IS 'Immutable sender-only funding/offer preparation history. Receiver safe RPCs never return sender total or margin. Financial acceptance/funding remains separately gated and not inferred from preparation.';